:[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://coloradoinsuranceappraiser.com/#website","url":"https://coloradoinsuranceappraiser.com/","name":"Colorado Insurance Appraiser","publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#webpage","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/","name":"How Insurance Appraisal Works in Colorado | 7 Stages","description":"A step-by-step guide to insurance appraisal in Colorado: the written demand, naming appraisers, selecting an umpire, negotiation and the award.","inLanguage":"en-US","isPartOf":{"@id":"https://coloradoinsuranceappraiser.com/#website"},"about":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"dateModified":"2026-11-17","breadcrumb":{"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#breadcrumb"},"primaryImageOfPage":{"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#primaryimage"},"image":{"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#primaryimage"},"mainEntity":{"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#howto"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://coloradoinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Resources","item":"https://coloradoinsuranceappraiser.com/resources/"},{"@type":"ListItem","position":3,"name":"Appraisal process","item":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/"}],"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#breadcrumb"},{"@type":"ImageObject","@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#primaryimage","url":"https://coloradoinsuranceappraiser.com/assets/img/photos/meeting.webp","contentUrl":"https://coloradoinsuranceappraiser.com/assets/img/photos/meeting.webp","width":1200,"height":797,"caption":"Conference table with notebooks and a laptop during a meeting"},{"@type":"HowTo","name":"How insurance appraisal works in Colorado","description":"The seven stages of a property insurance appraisal, from the disagreement to the signed award.","step":[{"@type":"HowToStep","position":1,"name":"The disagreement","text":"Coverage is accepted at least in part, but you and the insurer disagree on what the loss costs. Put the disagreement in writing with supporting documents.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-1"},{"@type":"HowToStep","position":2,"name":"The written demand","text":"Either side demands appraisal in writing, identifying the claim and invoking the policy’s appraisal provision.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-2"},{"@type":"HowToStep","position":3,"name":"Both sides name appraisers","text":"Each party selects a competent, impartial appraiser, usually within a set number of days after the demand.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-3"},{"@type":"HowToStep","position":4,"name":"Selecting an umpire","text":"The two appraisers choose a neutral umpire. If they can’t agree, a court can be asked to appoint one.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-4"},{"@type":"HowToStep","position":5,"name":"Appraiser negotiation","text":"The appraisers inspect, compare estimates line by line and agree on as many items as they can.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-5"},{"@type":"HowToStep","position":6,"name":"Umpire review","text":"Items the appraisers can’t resolve go to the umpire, who reviews each side’s support and decides.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-6"},{"@type":"HowToStep","position":7,"name":"The signed award","text":"A written award signed by any two of the three sets the amount of loss, and payment follows under the policy.","url":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#stage-7"}],"@id":"https://coloradoinsuranceappraiser.com/resources/appraisal-process/#howto"}]}</script>
